<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Librarian','Student','Super Admin','College Admin');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'&&has_role('Student')){$s=db()->prepare('SELECT id FROM students WHERE user_id=?');$s->execute([actor_id()]);$sid=(int)$s->fetchColumn();db()->prepare('INSERT INTO library_reservations(book_id,student_id,status) VALUES(?,? ,\'Active\')')->execute([(int)$_POST['book_id'],$sid]);$_SESSION['flash']=['success','Reservation placed'];redirect('reservations.php');}$books=db()->query("SELECT id,title FROM books WHERE status='Active' ORDER BY title")->fetchAll();page_top('Library Reservations');flash();if(has_role('Student')):?><div class='card p-4 mb-4'><form method='post' class='d-flex gap-2'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><select name='book_id' class='form-select'><?php foreach($books as $b):?><option value='<?=e($b['id'])?>'><?=e($b['title'])?></option><?php endforeach;?></select><button class='btn btn-primary'>Reserve</button></form></div><?php endif;?><div class='card p-3 table-responsive'><table class='table'><tr><th>Book</th><th>Student</th><th>Date</th><th>Status</th></tr><?php $r=db()->query('SELECT lr.*,b.title,u.name FROM library_reservations lr JOIN books b ON b.id=lr.book_id JOIN students s ON s.id=lr.student_id JOIN users u ON u.id=s.user_id ORDER BY lr.id DESC');foreach($r as $x):?><tr><td><?=e($x['title'])?></td><td><?=e($x['name'])?></td><td><?=e($x['reserved_at'])?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table></div><?php page_bottom();
